<?php
require_once __DIR__ . '/../includes/permissions.php';
require_role('teacher');
$pdo=db();
$teacher=$pdo->prepare('SELECT id,employee_number,title FROM teachers WHERE user_id=?'); $teacher->execute([current_user()['id']]); $profile=$teacher->fetch();
$stats=['responses'=>0,'average'=>null,'assignments'=>0];
if ($profile) {
    $q=$pdo->prepare('SELECT COUNT(DISTINCT e.id) responses,ROUND(AVG(a.rating_value),2) average FROM evaluations e LEFT JOIN evaluation_answers a ON a.evaluation_id=e.id WHERE e.teacher_id=? AND e.period_id IN (SELECT period_id FROM evaluations WHERE teacher_id=? GROUP BY period_id HAVING COUNT(*)>=3)');$q->execute([$profile['id'],$profile['id']]);$stats=$q->fetch();
    $q=$pdo->prepare('SELECT COUNT(*) FROM teacher_subjects WHERE teacher_id=?');$q->execute([$profile['id']]);$stats['assignments']=(int)$q->fetchColumn();
    $q=$pdo->prepare('SELECT c.name class_name,s.name subject_name,s.code,p.name period_name,COUNT(DISTINCT e.id) responses,ROUND(AVG(a.rating_value),2) average FROM teacher_subjects ts JOIN classes c ON c.id=ts.class_id JOIN subjects s ON s.id=ts.subject_id LEFT JOIN evaluation_periods p ON p.status IN ("open","closed") LEFT JOIN evaluations e ON e.teacher_id=ts.teacher_id AND e.class_id=ts.class_id AND e.subject_id=ts.subject_id AND e.period_id=p.id LEFT JOIN evaluation_answers a ON a.evaluation_id=e.id WHERE ts.teacher_id=? GROUP BY ts.id,p.id,c.name,s.name,s.code,p.name,p.starts_at ORDER BY p.starts_at DESC LIMIT 50');$q->execute([$profile['id']]);$results=$q->fetchAll();
    $q=$pdo->prepare('SELECT p.name period_name,c.name category,c.sort_order,p.starts_at,COUNT(DISTINCT e.id) responses,ROUND(AVG(a.rating_value),2) average FROM evaluations e JOIN evaluation_periods p ON p.id=e.period_id JOIN evaluation_answers a ON a.evaluation_id=e.id JOIN questions q ON q.id=a.question_id JOIN question_categories c ON c.id=q.category_id WHERE e.teacher_id=? GROUP BY p.id,c.id,p.name,c.name,c.sort_order,p.starts_at HAVING COUNT(DISTINCT e.id)>=3 ORDER BY p.starts_at DESC,c.sort_order LIMIT 100');$q->execute([$profile['id']]);$categoryResults=$q->fetchAll();
    $q=$pdo->prepare("SELECT ec.comment_text,ec.created_at,p.name period_name,s.name subject_name FROM evaluation_comments ec JOIN evaluations e ON e.id=ec.evaluation_id JOIN evaluation_periods p ON p.id=e.period_id JOIN subjects s ON s.id=e.subject_id WHERE e.teacher_id=? AND ec.visibility='teacher' AND (SELECT COUNT(*) FROM evaluations e2 WHERE e2.teacher_id=e.teacher_id AND e2.period_id=e.period_id)>=3 ORDER BY ec.created_at DESC LIMIT 20");$q->execute([$profile['id']]);$comments=$q->fetchAll();
} else {$results=[];$categoryResults=[];$comments=[];}
$pageTitle='Teacher overview';require __DIR__.'/../includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">TEACHER WORKSPACE</div><h1>Welcome, <?= e(current_user()['name']) ?></h1><p>Review your teaching assignments and aggregate student feedback.</p></div></div>
<?php if (!$profile): ?><div class="alert alert-warning">Your teacher profile has not been configured. Contact an administrator.</div><?php elseif(setting('results_visible_to_teachers','1')!=='1'): ?><div class="alert alert-info">Your school has temporarily disabled teacher-facing results. Please contact an administrator for details.</div><?php else: ?><div class="stats-grid stats-three"><article class="stat-card"><span class="stat-label">Assignments</span><strong><?= (int)$stats['assignments'] ?></strong><span class="stat-caption">Classes and subjects</span></article><article class="stat-card"><span class="stat-label">Submitted responses</span><strong><?= (int)$stats['responses'] ?></strong><span class="stat-caption">Periods meeting the 3-response threshold</span></article><article class="stat-card"><span class="stat-label">Overall average</span><strong><?= e(format_average($stats['average'])) ?><small class="out-of"> / 5</small></strong><span class="stat-caption">Aggregate for eligible periods</span></article></div>
<section class="panel"><div class="eyebrow">RESULTS</div><h2>Assignment overview</h2><p class="muted">Only aggregate scores are shown. Results for a period are held until at least 3 submissions are received.</p><div class="table-wrap"><table><thead><tr><th>Class</th><th>Subject</th><th>Period</th><th>Responses</th><th>Average</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><?= e($r['class_name']) ?></td><td><?= e($r['subject_name']) ?></td><td><?= e($r['period_name']??'—') ?></td><td><?= (int)$r['responses'] ?></td><td><?= (int)$r['responses']>=3?e(format_average($r['average'])):'Withheld' ?></td></tr><?php endforeach; ?><?php if(!$results): ?><tr><td colspan="5">No assignment results available yet.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="eyebrow">CATEGORY INSIGHTS</div><h2>Average by category</h2><?php if(!$categoryResults): ?><p class="muted">Category averages appear after at least three responses in that period.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Period</th><th>Category</th><th>Responses</th><th>Average</th></tr></thead><tbody><?php foreach($categoryResults as $result): ?><tr><td><?=e($result['period_name'])?></td><td><?=e($result['category'])?></td><td><?= (int)$result['responses']?></td><td><?=e(format_average($result['average']))?> / 5</td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel" id="feedback"><div class="eyebrow">STUDENT VOICE</div><h2>Comments</h2><?php if(setting('comments_enabled','1')!=='1'): ?><p class="muted">Written comments are disabled by your school.</p><?php elseif(!$comments): ?><p class="muted">Comments will be available when the minimum privacy threshold is met.</p><?php else: ?><div class="comment-list"><?php foreach($comments as $comment): ?><blockquote><?= e($comment['comment_text']) ?><footer><?= e($comment['subject_name'].' · '.$comment['period_name']) ?></footer></blockquote><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
<?php require __DIR__.'/../includes/footer.php'; ?>